mapper.select:
/* selectSellerMdCtUserSearchList */ SELECT S.ROWM, S.USER_ID, S.USER_NAME_LOC, S.PHONE_NUMBER, S.EMAIL, S.DEPARTMENT, S.DEPT_NAME, S.STATUS, S.STATUS_TEXT FROM ( SELECT ROWNUM ROWM, /* 순번 */ L.USER_ID, /* 사용자 ID */ L.USER_NAME_LOC, /* 사용자 이름 */ L.PHONE_NUMBER, /* 핸드폰번호 */ L.EMAIL, /* 이메일 */ L.DEPARTMENT, /* 부서코드 */ (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) DEPT_NAME, /* 부서명 */ L.STATUS, /* 상태 */ decode(L.STATUS,'D','삭제','사용') AS STATUS_TEXT /* 상태값 */ FROM ICOMLUSR L WHERE L.STATUS IN ('C','R') AND L.COM_CODE = #{st_com_code}
AND L.USER_ID = UPPER(#{st_search_user_id})
AND L.USER_NAME_LOC LIKE '%'||#{st_search_user_name}||'%'
AND L.DEPARTMENT = #{st_btoa_user_dept_code}
ORDER BY L.REG_DATE DESC ) S

