 		 	/*updateSellerMdCtUserSearchList*/
			UPDATE	ICOMLUSR
			SET		STATUS = 'D',
						EXPIRE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
						CONFIRM_USER_ID = #{st_user_id}
			WHERE	USER_ID = #{st_change_user_id}
			AND		COM_CODE = #{st_com_code}

mapper.select:
/* selectSellerMdCtUserSearchList_v2 */ SELECT L.USER_ID, L.USER_NAME_LOC, L.PHONE_NUMBER, L.EMAIL, L.DEPARTMENT, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) AS DEPT_NAME FROM ICOMLUSR L WHERE L.STATUS IN ('C','R') AND L.COM_CODE = #{st_com_code}
AND L.USER_NAME_LOC LIKE '%'||#{st_search_user_name}||'%'
AND EXISTS ( SELECT 1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT AND TEXT1 LIKE '%'||#{st_btoa_user_dept_name}||'%' )
ORDER BY L.REG_DATE DESC
